<template>
  <view class="con">
    <!-- 固定顶部区域（不滚动） -->
    <view class="top" id="top">
      <view class="page">
        <!-- 轮播区域 -->
        <swiper class="custom-swiper" v-if="swiperList && swiperList.length > 0" :indicator-dots="true" :autoplay="false" :interval="3000" :duration="500" :circular="true" indicator-color="#999" indicator-active-color="#ff0000">
          <swiper-item v-for="(item, i) in swiperList" :key="i">
            <view class="swiper-item" @click="toDetail(item.id)">
              <view class="item-text">
                <view class="match-header">
                  <text class="match-round"> {{ item.league_name }}第{{ item.round_no }}轮 </text>
                  <text class="match-date">{{ forateData(item.race_date) }}</text>
                </view>
                <view class="teams-container">
                  <text class="team-name home">{{ item.home_name }}</text>
                  <text class="vs-separator">:</text>
                  <text class="team-name away">{{ item.visiting_name }}</text>
                </view>
                <view class="odds-container">
                  <text class="odds home-odds">{{ item.home_win_rate ? decimalToPercentage(item.home_win_rate, 0) : "" }}</text>
                  <text class="odds-separator">:</text>
                  <text class="odds away-odds">{{ item.visiting_win_rate ? decimalToPercentage(item.visiting_win_rate, 0) : "" }}</text>
                </view>
              </view>
            </view>
          </swiper-item>
        </swiper>
      </view>
      <!-----大洲名--------->
      <view class="continent-container">
        <view v-for="(item, index) in continentList" :key="index" :class="['continent-item', { active: currentContinentIndex === index }]" @click="handleClickContinent(index)">
          {{ item.continentName }}
        </view>
      </view>
      <!-----联赛名--------->
      <view class="tab-container">
        <scroll-view scroll-x class="tab-scroll" scroll-with-animation>
          <view v-for="(item, index) in leagueList" :id="'tab' + index" :key="index" class="tab-item" :class="{ active: leagueCurrentIndex === index }" @tap="clickLeague(index, item)">
            {{ item.league_name }}
          </view>
        </scroll-view>
      </view>
      <view class="tab">
        <view class="tab-two">
          <view :class="['tab-item-two', activeIndex == 0 ? 'active' : '']" @click="clickBang(0)"> 赛程 </view>
          <view v-if="selectTopTabValue.is_have_points == 1" :class="['tab-item-two', activeIndex == 1 ? 'active' : '']" @click="clickBang(1)"> 积分 </view>
          <view v-if="selectTopTabValue.is_have_scorer == 1" :class="['tab-item-two', activeIndex == 2 ? 'active' : '']" @click="clickBang(2)">射手</view>
          <view class="picker-box">
            <picker mode="selector" :range="csList" @change="handleChangeCs">
              <view style="font-size: 26rpx; color: #666; text-align: right">{{ selectedCs }}</view>
            </picker>
          </view>
        </view>
        <view class="tab-r">
          <text class="t-r-c">{{ selectTopTabValue.league_name }}</text>
        </view>
      </view>
      <scroll-view v-if="activeIndex == 0 && stageList && stageList.length > 1" class="tabs-scroll-container" scroll-x show-scrollbar="false" :scroll-with-animation="true">
        <view class="match-tabs">
          <view v-for="(tab, index) in stageList" :key="index" :class="['other-tab', { active: stageSelectIndex === index }]" @click="handleClickGroupStageRound(index, tab,'stage')">
            {{ tab }}
          </view>
        </view>
      </scroll-view>
      <template v-if="activeIndex == 0&&groupList&&groupList.length > 0">
        <scroll-view v-if="activeIndex == 0" class="tabs-scroll-container" scroll-x show-scrollbar="false" :scroll-with-animation="true">
          <view class="match-tabs">
            <view class="overview-tab" @click="handleClickGroupStageRound(0, '','subGroup')">总览</view>
            <view v-for="(tab, index) in groupList" :key="index" :class="['other-tab', { active: groupIndex === index + 1 }]" @click="handleClickGroupStageRound(index + 1, tab,'subGroup')">
              {{ tab }}
            </view>
          </view>
        </scroll-view>
      </template>
      <template v-if="activeIndex == 0&&roundList && roundList.length > 0">
        <view class="tab-container" v-if="activeIndex == 0">
          <view class="tab-stage-t" style="background: #73adde; color: #fff; font-size: 24rpx">轮</view>
          <scroll-view scroll-x class="stage-scroll" scroll-with-animation :scroll-left="scrollLeft">
            <view v-for="(item, index) in roundList" :id="'tab' + index" :key="index" class="tab-stage" :class="{ active: roundIndex == index }" @tap="handleClickRound(index, item,'roundNo')">
              {{ item.no }}
            </view>
          </scroll-view>
        </view>
      </template>
    </view>

    <!-- 内容滚动区域（只滚动这部分） -->
    <view class="content-scroll">
      <view v-if="activeIndex == 0" class="saicheng">
        <view v-for="(item, index) in courseList" :key="index" class="item">
          <view class="time">
            <text>{{ forateData(item.race_date) }}</text>
            <view v-if="item.is_over == 0 && item.home_win_rate != 0" class="ai" @tap="toDetail(item)"> 分析 </view>
          </view>
          <view class="score">
            <text class="name-l">{{ item.home_name }}</text>
            <text class="score-con" style="text-align: right" v-if="item.home_goal || item.home_goal == 0">{{ item.home_goal }}</text>
            <text class="score-con" style="width: 6%; text-align: center">:</text>
            <text class="score-con" v-if="item.visiting_goal || item.visiting_goal == 0">{{ item.visiting_goal }}</text>
            <text class="name-r">{{ item.visiting_name }}</text>
          </view>
        </view>
      </view>
      <view class="jifen" v-if="activeIndex === 1">
        <view class="table-container">
          <view class="table-header">
            <view class="header-border"></view>
            <view class="header-item" style="width: 15%">排名</view>
            <view class="header-item" style="width: 25%">球队</view>
            <view class="header-item" style="width: 12%">场次</view>
            <view class="header-item" style="width: 12%">胜</view>
            <view class="header-item" style="width: 12%">平</view>
            <view class="header-item" style="width: 12%">负</view>
            <view class="header-item" style="width: 12%">积分</view>
          </view>
          <view class="table-body">
            <view class="table-row" v-for="(team, index) in jifenList" :key="index">
              <view class="row-border first-rank"></view>
              <view class="body-item" style="width: 15%">{{ team.ranking_no }}</view>
              <view class="body-item team-name" style="width: 25%">{{ team.team_name }}</view>
              <view class="body-item" style="width: 12%">{{ team.matches_number }}</view>
              <view class="body-item" style="width: 12%">{{ team.vin_number }}</view>
              <view class="body-item" style="width: 12%">{{ team.equality_number }}</view>
              <view class="body-item" style="width: 12%">{{ team.fail_number }}</view>
              <view class="body-item" style="width: 12%">{{ team.points }}</view>
            </view>
          </view>
        </view>
      </view>
      <view class="sheshou" v-if="activeIndex == 2">
        <view class="table">
          <view class="table-row header">
            <view class="table-cell" style="width: 10%">排名</view>
            <view class="table-cell" style="width: 30%">球员</view>
            <view class="table-cell" style="width: 30%">球队</view>
            <view class="table-cell" style="width: 10%">总</view>
            <view class="table-cell" style="width: 10%">普</view>
            <view class="table-cell" style="width: 10%">点</view>
          </view>
          <view class="table-row" v-for="(item, index) in sheshouList" :key="index">
            <view class="table-cell" style="width: 10%">{{ item.ranking_no }}</view>
            <view class="table-cell" style="width: 30%">{{ item.player_name }}</view>
            <view class="table-cell" style="width: 30%">{{ item.team_name }}</view>
            <view class="table-cell" style="width: 10%">{{ item.total_goal }}</view>
            <view class="table-cell" style="width: 10%">{{ item.normal_goal }}</view>
            <view class="table-cell" style="width: 10%">{{ item.penalty_kick_goal }}</view>
          </view>
        </view>
      </view>
      <view v-if="(courseList.length == 0 && activeIndex == 0) || (activeIndex == 1 && jifenList.length == 0) || (activeIndex == 2 && sheshouList.length == 0)">
        <noData> </noData>
      </view>
    </view>

    <view class="reminder-dialog" v-if="isDialogShow">
      <view class="dialog-content">
        <text class="dialog-title">提示</text>
        <text class="dialog-message">您的灵石不足，请兑换！</text>
        <view class="dialog-buttons">
          <button class="dialog-btn cancel-btn" @tap="handleCancel">取消</button>
          <button class="dialog-btn exchange-btn" @tap="handleExchange">兑换</button>
        </view>
      </view>
    </view>
  </view>
</template>

<script>
import { login, checkToken } from "@/utils/auth";
import { queryContinentList, queryLeagueList, getSaiCheng, getJiFen, getSheShou, getTimeList, queryStageList, getHaveMoney, queryGroupAndRoundList } from "@/api/demo";
import { formatDateWithWeekday } from "@/utils/data";
import lun from "@/pages/prediction/index";
import noData from "@/pages/commn/noData";
import SwiperCarousel from "@/pages/commn/SwiperCarousel.vue";
export default {
  components: {
    lun,
    noData,
    SwiperCarousel
  },
  data() {
    return {
      leagueList: [],
      csList: [],
      courseList: [],
      tabs: [],
      tabBang: ["赛程", "积分", "射手"],
      activeIndex: 0,
      list: [],
      status: {
        0: "未开始",
        1: "已结束",
      },
      selectedCs: "",
      param: {},
      leagueCurrentIndex: 0,
      tabValue: "",
      selectTopTabValue: {},
      jifenList: [],
      sheshouList: [],
      roundList: [],
      stage: "",
      roundNo: null,
      currentSelectRound: null,
      currentSelectGroup: null,
      stageList: [],
      stageSelectIndex: 0,
      stageSelectValue: "",
      roundListIndex: 0,
      list1Index: null,
      isDialogShow: false,
      contentScrollW: 0,
      contentScrollNameW: 0,
      roundIndex: 0,
      scrollLeft: 0,
      stageTabArr: [
        { id: 0, stage: "小组赛", isDisabled: true, isDefault: false },
        { id: 1, stage: "淘汰赛", isDisabled: true, isDefault: true },
        { id: 2, stage: "决赛", isDisabled: true, isDefault: true },
      ],
      isSticky: false,
      placeholderHeight: "0",
      scrollTop: 0,
      offsetTop: 150,
      stickyOffset: 88,
      swiperList: [],
      tabIndex: 0,
      isShowMiddle: false,
      groupIndex: -1,
      groupList: [],
      groupAMatches: [],
      currentContinentIndex: 0,
      continentList: [],
    };
  },
  onShow() {},
  onLoad() {
    queryContinentList().then((res) => {
      this.continentList = res.data;
    });
    this.loadData();
    this.getSwiperList();
  },
  mounted() {
    this.initScrollData();
  },
  methods: {
    async getCommonTimeList(leagueName, dataType) {
      try {
        const res = await getTimeList({ leagueName, dataType });
        return res.data || [];
      } catch (err) {
        console.error('getCommonTimeList error:', err);
        return [];
      }
    },
    async getCommonStageList(leagueName, cs) {
      try {
        const res = await queryStageList({ leagueName, cs });
        return res.data || [];
      } catch (err) {
        console.error('getCommonStageList error:', err);
        return [];
      }
    },
    async getCommonRoundGroup(leagueName, stage, cs) {
      try {
        const res = await queryGroupAndRoundList({ leagueName, stage, cs });
        const { roundList = [], groupList = [] } = res.data || {};
        const formattedRoundList = roundList.map((item, i) => ({
          no: item,
          id: i,
          left: 0,
          width: 0
        }));
        return { roundList: formattedRoundList, groupList };
      } catch (err) {
        console.error('getCommonRoundGroup error:', err);
        return { roundList: [], groupList: [] };
      }
    },
    async getCommonSaiCheng(params) {
      try {
        const res = await getSaiCheng(params);
        return res.data || [];
      } catch (err) {
        console.error('getCommonSaiCheng error:', err);
        return [];
      }
    },
    async getCommonRankData(apiFn, leagueName, cs) {
      try {
        const res = await apiFn({ leagueName, cs });
        return res.data || [];
      } catch (err) {
        console.error(`getCommonRankData (${apiFn.name}) error:`, err);
        return [];
      }
    },
    async handleClickContinent(index) {
      this.currentContinentIndex = index;
      const { continentName } = this.continentList[index];
      try {
        const leagueRes = await queryLeagueList({ fromContinent: continentName });
        this.leagueList = leagueRes.data.leagueList || [];
        if (this.leagueList.length === 0) return;
        this.selectTopTabValue = this.leagueList[0];
        this.leagueCurrentIndex = 0;
        this.scrollLeft = 0;
        const csList = await this.getCommonTimeList(this.selectTopTabValue.league_name, "course");
        this.csList = csList;
        this.selectedCs = csList[0] || "";
        if (!this.selectedCs) return;
        const stageList = await this.getCommonStageList(this.selectTopTabValue.league_name, this.selectedCs);
        this.stageList = stageList;
        this.stageSelectIndex = stageList.findIndex(item => item === this.selectTopTabValue.stage) || 0;
        this.stageSelectValue = stageList[this.stageSelectIndex] || "";
        const { roundList, groupList } = await this.getCommonRoundGroup(
          this.selectTopTabValue.league_name,
          this.stageSelectValue,
          this.selectedCs
        );
        this.roundList = roundList;
        this.groupList = groupList;
        this.currentSelectRound = this.selectTopTabValue.round_no || "";
        this.roundIndex = 0;
        const courseList = await this.getCommonSaiCheng({
          leagueName: this.selectTopTabValue.league_name,
          cs: this.selectedCs,
          stage: this.stageSelectValue,
          roundNo: this.currentSelectRound,
          subGroup: groupList[0] || ""
        });
        this.courseList = courseList;
        this.initScrollData();
      } catch (err) {
        console.error('handleClickContinent error:', err);
      }
    },
    async handleClickGroupStageRound(index, item, type) {
      const params = {
        leagueName: this.selectTopTabValue.league_name,
        cs: this.selectedCs,
        stage: this.stageSelectValue,
        subGroup: "",
        roundNo: ""
      };
      switch (type) {
        case 'stage':
          params.stage = item;
          this.stageSelectIndex = index;
          break;
        case 'subGroup':
          params.subGroup = item;
          this.groupIndex = index;
          break;
        case 'roundNo':
          params.roundNo = item.no;
          this.roundIndex = index;
          break;
      }
      this.courseList = await this.getCommonSaiCheng(params);
    },
    tabChange(index) {
      this.tabIndex = index;
    },
    decimalToPercentage(decimal, fixed = 0, defaultValue = "--") {
      if (typeof decimal !== "number" || isNaN(decimal)) return defaultValue;
      return `${(decimal * 100).toFixed(fixed)}%`;
    },
    async getSwiperList() {
      try {
        const res = await getSwiper();
        this.swiperList = res.data || [];
      } catch (err) {
        console.error('getSwiperList error:', err);
      }
    },
    handleCarouselChange() {},
    initScrollData() {
      this.scrollLeft = "0";
      this.$nextTick(() => {
        this.getScrollW();
        if (this.roundList[this.roundIndex]) {
          this.scrollLeft = this.roundList[this.roundIndex].left 
            - this.contentScrollW / 2 
            + this.roundList[this.roundIndex].width / 2;
        }
      });
    },
    getScrollW() {
      const query = uni.createSelectorQuery().in(this);
      query.select(".stage-scroll").boundingClientRect(data => {
        this.contentScrollW = data?.width || 0;
      }).exec();
      query.selectAll(".tab-stage").boundingClientRect(data => {
        if (data.length && this.roundList.length) {
          data.forEach((item, i) => {
            this.roundList[i] = { ...this.roundList[i], left: item.left, width: item.width };
          });
        }
      }).exec();
    },
    clickIsReturn(type) {
      return !this.stageTabArr.some((item, i) => i + 1 === type && item.isDisabled);
    },
    updateActiveIndex(type) {
      this.stageTabArr.forEach((item, i) => {
        this.$set(item, "isDefault", i + 1 === type);
      });
    },
    async clickStageItem(item, type, i) {
      this.roundListIndex = type === 1 ? i : null;
      this.list1Index = type === 2 ? i : null;
      if (!this.clickIsReturn(type)) return;
      this.updateActiveIndex(type);
      this.courseList = await this.getCommonSaiCheng({
        leagueName: this.selectTopTabValue.league_name,
        cs: this.selectedCs,
        stage: type === 1 ? "小组赛" : item,
        roundNo: type === 1 ? item : ""
      });
    },
    handleExchange() {
      uni.navigateTo({ url: "/pages/recharge/recharge" });
      this.isDialogShow = false;
    },
    handleCancel() {
      this.isDialogShow = false;
    },
    async toDetail(item) {
      try {
        await getHaveMoney({
          courseId: item.id,
          coinAmount: item.coin_amount || ""
        });
        uni.navigateTo({ url: `/pages/test/index?id=${item.id}` });
      } catch (err) {
        console.error('toDetail error:', err);
      }
    },
    forateData(time) {
      return formatDateWithWeekday(time);
    },
    async handleChangeCs(e) {
      const leagueName = this.selectTopTabValue.league_name;
      this.selectedCs = this.csList[e.detail.value] || "";
      if (!this.selectedCs) return;
      try {
        if (this.activeIndex === 0) {
          const [courseList, stageList, roundGroupData] = await Promise.all([
            this.getCommonSaiCheng({
              leagueName,
              cs: this.selectedCs,
              stage: this.selectTopTabValue.stage || "",
              roundNo: this.selectTopTabValue.round_no || ""
            }),
            this.getCommonStageList(leagueName, this.selectedCs),
            this.getCommonRoundGroup(leagueName, this.selectTopTabValue.stage || "", this.selectedCs)
          ]);
          this.courseList = courseList;
          this.stageList = stageList;
          if (this.selectTopTabValue.show_type === "stage") {
            this.roundList = roundGroupData.roundList;
          } else if (this.selectTopTabValue.show_type === "national") {
            this.roundList = roundGroupData.roundList;
          }
        } else if (this.activeIndex === 1) {
          this.jifenList = await this.getCommonRankData(getJiFen, leagueName, this.selectedCs);
        } else {
          this.sheshouList = await this.getCommonRankData(getSheShou, leagueName, this.selectedCs);
        }
      } catch (err) {
        console.error('handleChangeCs error:', err);
      }
    },
    async checkLogin() {
      const tokenValid = await checkToken();
      if (!tokenValid) await login();
    },
    async clickBang(index, item) {
      this.activeIndex = index;
      this.roundList = [];
      const leagueName = this.selectTopTabValue.league_name;
      const typeMap = ['course', 'points', 'scorer'];
      const dataType = typeMap[index];
      try {
        const csList = await this.getCommonTimeList(leagueName, dataType);
        this.csList = csList;
        this.selectedCs = csList[0] || "";
        if (!this.selectedCs) return;
        const [stageList, roundGroupData] = await Promise.all([
          this.getCommonStageList(leagueName, this.selectedCs),
          this.getCommonRoundGroup(leagueName, "", this.selectedCs)
        ]);
        this.stageList = stageList;
        this.stageSelectIndex = stageList.findIndex(item => item === this.selectTopTabValue.stage) || 0;
        this.stageSelectValue = stageList[this.stageSelectIndex] || "";
        this.roundList = roundGroupData.roundList;
        this.groupList = roundGroupData.groupList;
        this.currentSelectRound = this.selectTopTabValue.round_no || "";
        this.roundIndex = 0;
        switch (index) {
          case 0:
            this.courseList = await this.getCommonSaiCheng({
              leagueName,
              cs: this.selectedCs,
              stage: this.selectTopTabValue.stage || "",
              roundNo: this.currentSelectRound
            });
            break;
          case 1:
            this.jifenList = await this.getCommonRankData(getJiFen, leagueName, this.selectedCs);
            break;
          case 2:
            this.sheshouList = await this.getCommonRankData(getSheShou, leagueName, this.selectedCs);
            break;
        }
      } catch (err) {
        console.error('clickBang error:', err);
      }
    },
    async initData() {
      this.showLoading();
      try {
        const continentResult = await queryContinentList();
        this.continentList = continentResult.data || [];
        this.currentContinentIndex = this.continentList.findIndex(item => item.isSelect === 1) || 0;
        if (this.continentList.length === 0) return;
        const leagueRes = await queryLeagueList({
          fromContinent: this.continentList[this.currentContinentIndex].continentName
        });
        this.leagueList = leagueRes.data.leagueList || [];
        if (this.leagueList.length === 0) return;
        this.selectTopTabValue = this.leagueList[0];
        this.leagueCurrentIndex = 0;
        uni.setStorageSync("isShow", true);
        this.isShowMiddle = true;
        const csList = await this.getCommonTimeList(this.selectTopTabValue.league_name, "course");
        this.csList = csList;
        this.selectedCs = csList[0] || "";
        if (!this.selectedCs) return;
        const [stageList, roundGroupData, courseList] = await Promise.all([
          this.getCommonStageList(this.selectTopTabValue.league_name, this.selectedCs),
          this.getCommonRoundGroup(
            this.selectTopTabValue.league_name,
            "",
            this.selectedCs
          ),
          this.getCommonSaiCheng({
            leagueName: this.selectTopTabValue.league_name,
            cs: this.selectedCs,
            roundNo: this.selectTopTabValue.round_no || ""
          })
        ]);
        this.stageList = stageList;
        this.stageSelectIndex = stageList.findIndex(item => item === this.selectTopTabValue.stage) || 0;
        this.stageSelectValue = stageList[this.stageSelectIndex] || "";
        this.roundList = roundGroupData.roundList;
        this.groupList = roundGroupData.groupList;
        this.currentSelectRound = this.selectTopTabValue.round_no || "";
        this.roundIndex = 0;
        this.courseList = courseList;
        this.initScrollData();
      } catch (err) {
        console.error('initData error:', err);
      }
      this.hideLoading();
    },
    loadData() {
      this.initData();
    },
    loadMore() {
      this.loadData();
    },
    async handleClickRound(index, item) {
      this.currentSelectRound = item;
      this.roundIndex = index;
      this.$nextTick(() => {
        this.getScrollW();
        if (this.roundList[index]) {
          this.scrollLeft = this.roundList[index].left 
            - this.contentScrollW / 2 
            + this.roundList[index].width / 2;
        }
      });
      this.courseList = await this.getCommonSaiCheng({
        leagueName: this.selectTopTabValue.league_name,
        cs: this.selectedCs,
        roundNo: item.no,
        stage: this.stageSelectValue,
        subGroup: this.groupList[0] || ""
      });
    },
    async clickLeague(index, item) {
      if (this.leagueCurrentIndex === index) return;
      this.tabValue = item.league_name;
      this.selectTopTabValue = item;
      this.leagueCurrentIndex = index;
      const csList = await this.getCommonTimeList(item.league_name, "course");
      this.csList = csList;
      this.selectedCs = csList[0] || "";
      if (!this.selectedCs) return;
      const [stageList, roundGroupData, courseList] = await Promise.all([
        this.getCommonStageList(item.league_name, this.selectedCs),
        this.getCommonRoundGroup(item.league_name, "", this.selectedCs),
        this.getCommonSaiCheng({
          leagueName: item.league_name,
          cs: this.selectedCs,
          roundNo: item.round_no || ""
